import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.model.vocabulary.RDFS;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.rio.helpers.AbstractRDFHandler;

/** Converts a complete Turtle graph into the SPARQL Results shape used by the Graph Explorer benchmark. */
public final class TurtleSparqlResults {
	private TurtleSparqlResults() {
	}

	public static void main(String[] args) throws Exception {
		if (args.length != 3) {
			throw new IllegalArgumentException("Usage: TurtleSparqlResults <input.ttl> <results.json> <summary.json>");
		}
		Path input = Path.of(args[0]);
		Path resultsPath = Path.of(args[1]);
		Path summaryPath = Path.of(args[2]);
		List<Statement> parsed = new ArrayList<>();
		try (InputStream stream = Files.newInputStream(input)) {
			Rio.createParser(RDFFormat.TURTLE)
					.setRDFHandler(new AbstractRDFHandler() {
						@Override
						public void handleStatement(Statement statement) {
							parsed.add(statement);
						}
					})
					.parse(stream, input.toUri().toString());
		}
		Set<Statement> statements = new LinkedHashSet<>(parsed);
		writeResults(resultsPath, statements);
		writeSummary(summaryPath, input, parsed.size(), statements);
	}

	private static void writeResults(Path path, Set<Statement> statements) throws IOException {
		StringBuilder json = new StringBuilder(256 + statements.size() * 400);
		json.append("{\"head\":{\"vars\":[\"source\",\"predicate\",\"target\"]},\"results\":{\"bindings\":[");
		boolean first = true;
		for (Statement statement : statements) {
			if (!first) {
				json.append(',');
			}
			first = false;
			json.append("{\"source\":");
			appendTerm(json, statement.getSubject());
			json.append(",\"predicate\":");
			appendTerm(json, statement.getPredicate());
			json.append(",\"target\":");
			appendTerm(json, statement.getObject());
			json.append('}');
		}
		json.append("]}}\n");
		Files.writeString(path, json, StandardCharsets.UTF_8);
	}

	private static void writeSummary(Path path, Path input, int parsedCount, Set<Statement> statements) throws IOException {
		Set<Value> terms = new HashSet<>();
		Set<Resource> resources = new HashSet<>();
		Set<Literal> literals = new HashSet<>();
		Set<Value> typeTargets = new HashSet<>();
		Set<Value> linked = new HashSet<>();
		Set<IRI> predicates = new HashSet<>();
		long labelStatements = 0;
		long drawnEdges = 0;
		for (Statement statement : statements) {
			terms.add(statement.getSubject());
			terms.add(statement.getObject());
			resources.add(statement.getSubject());
			if (statement.getObject() instanceof Resource resource) {
				resources.add(resource);
			} else if (statement.getObject() instanceof Literal literal) {
				literals.add(literal);
			}
			predicates.add(statement.getPredicate());
			if (statement.getPredicate().equals(RDF.TYPE)) {
				typeTargets.add(statement.getObject());
			} else if (!(statement.getObject() instanceof Literal)) {
				linked.add(statement.getSubject());
				linked.add(statement.getObject());
				drawnEdges++;
			}
			if (statement.getPredicate().equals(RDFS.LABEL)) {
				labelStatements++;
			}
		}
		long hiddenTypeTargets = typeTargets.stream().filter(target -> !linked.contains(target)).count();
		long drawnNodes = resources.stream().filter(node -> !typeTargets.contains(node) || linked.contains(node)).count();
		long iris = terms.stream().filter(IRI.class::isInstance).count();
		long blankNodes = terms.stream().filter(BNode.class::isInstance).count();
		long distinctLiterals = terms.stream().filter(Literal.class::isInstance).count();
		String json = "{\n"
				+ "  \"input\": " + quoted(input.toAbsolutePath().toString()) + ",\n"
				+ "  \"inputBytes\": " + Files.size(input) + ",\n"
				+ "  \"parsedStatementEvents\": " + parsedCount + ",\n"
				+ "  \"distinctStatements\": " + statements.size() + ",\n"
				+ "  \"duplicateStatementEvents\": " + (parsedCount - statements.size()) + ",\n"
				+ "  \"distinctSubjectObjectTerms\": " + terms.size() + ",\n"
				+ "  \"iris\": " + iris + ",\n"
				+ "  \"blankNodes\": " + blankNodes + ",\n"
				+ "  \"literals\": " + distinctLiterals + ",\n"
				+ "  \"resourceNodes\": " + resources.size() + ",\n"
				+ "  \"literalNodes\": " + literals.size() + ",\n"
				+ "  \"predicates\": " + predicates.size() + ",\n"
				+ "  \"rdfsLabelStatements\": " + labelStatements + ",\n"
				+ "  \"defaultDrawnNodesShowValuesFalse\": " + drawnNodes + ",\n"
				+ "  \"defaultDrawnEdgesNonTypeNonLiteral\": " + drawnEdges + ",\n"
				+ "  \"typeOnlyTargetsHidden\": " + hiddenTypeTargets + ",\n"
				+ "  \"includeRoutesBelowSourceThreshold500\": " + (drawnNodes < 500) + "\n"
				+ "}\n";
		Files.writeString(path, json, StandardCharsets.UTF_8);
	}

	private static void appendTerm(StringBuilder json, Value value) {
		if (value instanceof IRI iri) {
			json.append("{\"type\":\"uri\",\"value\":");
			appendString(json, iri.stringValue());
			json.append('}');
		} else if (value instanceof BNode blankNode) {
			json.append("{\"type\":\"bnode\",\"value\":");
			appendString(json, blankNode.getID());
			json.append(",\"rdf4j:reference\":true}");
		} else if (value instanceof Literal literal) {
			json.append("{\"type\":\"literal\",\"value\":");
			appendString(json, literal.getLabel());
			literal.getLanguage().ifPresent(language -> {
				json.append(",\"xml:lang\":");
				appendString(json, language);
			});
			if (literal.getLanguage().isEmpty()) {
				json.append(",\"datatype\":");
				appendString(json, literal.getDatatype().stringValue());
			}
			json.append('}');
		} else if (value instanceof TripleTerm triple) {
			json.append("{\"type\":\"triple\",\"value\":{\"subject\":");
			appendTerm(json, triple.getSubject());
			json.append(",\"predicate\":");
			appendTerm(json, triple.getPredicate());
			json.append(",\"object\":");
			appendTerm(json, triple.getObject());
			json.append("}}");
		} else {
			throw new IllegalArgumentException("Unsupported RDF term: " + value.getClass().getName());
		}
	}

	private static String quoted(String value) {
		StringBuilder json = new StringBuilder();
		appendString(json, value);
		return json.toString();
	}

	private static void appendString(StringBuilder json, String value) {
		json.append('"');
		for (int i = 0; i < value.length(); i++) {
			char character = value.charAt(i);
			switch (character) {
			case '"' -> json.append("\\\"");
			case '\\' -> json.append("\\\\");
			case '\b' -> json.append("\\b");
			case '\f' -> json.append("\\f");
			case '\n' -> json.append("\\n");
			case '\r' -> json.append("\\r");
			case '\t' -> json.append("\\t");
			default -> {
				if (character < 0x20) {
					json.append(String.format("\\u%04x", (int) character));
				} else {
					json.append(character);
				}
			}
			}
		}
		json.append('"');
	}
}
